-- Runs once when Hyprland starts (the old exec-once), not on every reload.
local function exec_once(cmd)
    hl.on("hyprland.start", function() hl.exec_cmd(cmd) end)
end

exec_once("systemctl --user start hyprpolkitagent")
exec_once("hypridle")
exec_once("quickshell -p ~/.config/hypr/scripts/quickshell/Shell.qml")
